function w({registerIndicator:f,sourceValues:y,nulls:b}){f({id:"oa-dema",name:"Double Exponential Moving Average (DEMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"dema",type:"line",title:"DEMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(n,i){const h=Math.max(1,Math.floor(Number(i.period)||10)),M=y(n,i.source??"close"),a=2/(h+1),g=1-a;let u=!0,c=1,t=0,e=0,o=0,r=0;const m=new Array(n.length).fill(NaN);for(let l=0;l<n.length;l++){const s=M[l];if(Number.isFinite(s)){if(t=a*(s-t)+t,u){c*=g;const d=1-c,p=d!==0?1/d:1;o=p*t,e=a*(o-e)+e,r=p*e,u=c>1e-10}else o=t,e=a*(o-e)+e,r=e;m[l]=2*o-r}}return{dema:b(m)}}})}export{w as default};
